C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Understand that you earn a commission only when a reader buys through your link, so a small trusted audience can outperform a large indifferent one.', "Read each programme's terms for cookie length, payment threshold and banned methods before you join, and keep a copy of the terms."], ['Choose a niche you can write about for 50 articles, check that people search for it, and confirm related products pay a reasonable commission.', 'Test the idea by listing twenty questions buyers ask in this niche; if you cannot find twenty, the niche may be too narrow.'], ['Only recommend products you have tried or researched deeply, and compare at least three alternatives so your advice is fair to the reader.', "Look at refund rate, support quality and the seller's reputation, and drop partners who are slow to pay or hard to contact."], ['Write guides that answer one clear question each, with a short summary at the top, honest pros and cons and a plain recommendation.', 'Update each article every six months to check prices, links and facts, and note the update date so readers know it is current.'], ['Place a clear statement near each link that you may earn a commission, in plain words, before the reader clicks and not buried in a footer.', 'Never claim results you have not seen, never fake reviews, and follow the advertising rules of your country and each platform you use.'], ['Build traffic with useful articles, an email list and honest social posts, aiming for steady growth such as 10 percent more visitors a month.', 'Avoid spam, hidden links and paid fake engagement, since these can get your account banned and harm trust that took months to earn.'], ['Use a unique tracking link for each article and record clicks, sales and earnings in a sheet, then work out earnings per click.', 'Calculate profit by subtracting hosting, tools and ad costs from commission, and decide which three articles deserve more effort next month.'], ['Every quarter, review your top and bottom pages, retire weak ones, and set a target such as two new guides and one update each month.', 'Write a one-page plan with goals, schedule and budget, and review it with a trusted friend who will tell you honestly what is unclear.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
